  zombies = active.filter(w => !isErrorWf(w) && !seen.has(String(w.id))).map(w => String(w.name || w.id));
} else zombieNote = 'Idle-workflow check skipped: only ' + windowDays.toFixed(1) + ' days of executions were fetched (need 7+).';

const warn = failed24.length > 0 || openWebhooks.length > 0 || withSecrets.length > 0 || noErrorWf.length > 0 || longRuns.length > 0;
const L = [];
L.push((warn ? '🩺' : '✅') + ' <b>n8n health</b>');
L.push('Workflows: ' + workflows.length + ' (' + active.length + ' active, ' + (workflows.length - active.length) + ' inactive)');
L.push('Executions in the last 24 h: ' + last24.length + ', failed: ' + failed24.length + (last24.length ? ' (' + Math.round(rate * 100) + '%)' : ''));
if (topFailing.length) { L.push('', '<b>Most failures</b>'); for (const [id, n] of topFailing) L.push('• ' + esc(nameOf.get(id) || ('workflow ' + id)) + ': ' + n); }
if (longRuns.length) L.push('', '⏱ ' + longRuns.length + ' execution(s) ran longer than 10 min (longest ' + Math.round(longest / 60000) + ' min)');
if (openWebhooks.length) { L.push('', '🔓 <b>Active webhooks without authentication</b>'); for (const x of openWebhooks.slice(0, 8)) L.push('• ' + esc(x)); if (openWebhooks.length > 8) L.push('and ' + (openWebhooks.length - 8) + ' more'); }
if (withSecrets.length) { L.push('', '🔑 <b>Hardcoded secrets</b> in: ' + esc(withSecrets.slice(0, 8).map(x => x.name).join(', ')) + (withSecrets.length > 8 ? ' and ' + (withSecrets.length - 8) + ' more' : '')); }
if (noErrorWf.length) { L.push('', '📭 ' + noErrorWf.length + ' active workflow(s) have no Error Workflow: ' + esc(noErrorWf.slice(0, 6).map(w => w.name || w.id).join(', ')) + (noErrorWf.length > 6 ? ' ...' : '')); }
if (zombies.length) L.push('', '💤 Active but no execution in ' + Math.floor(windowDays) + ' days: ' + esc(zombies.slice(0, 8).join(', ')) + (zombies.length > 8 ? ' and ' + (zombies.length - 8) + ' more' : ''));
if (zombieNote) L.push('', esc(zombieNote));
if (execErrors) L.push('', '⚠️ Some execution pages could not be read, so counts may be low.');
return [{ json: { text: L.join('\n').slice(0, 3800), stats: { workflows: workflows.length, active: active.length, executions_24h: last24.length, failed_24h: failed24.length,
  open_webhooks: openWebhooks.length, secrets: withSecrets.length, no_error_workflow: noErrorWf.length, zombies: zombies.length, long_runs: longRuns.length } } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
